120	#ifdef HAVE_OPENSSL
121	#  if OPENSSL_VERSION_NUMBER >= 0x30000000L
122	  // RC4 is in the legacy provider.
123	  legacy_provider_ = OSSL_PROVIDER_load(nullptr, "legacy");
124	  if (!legacy_provider_) {
125	    throw DL_ABORT_EX("OSSL_PROVIDER_load 'legacy' failed.");
126	  }
127	
