129	  if (!default_provider_) {
130	    throw DL_ABORT_EX("OSSL_PROVIDER_load 'default' failed.");
131	  }
132	#  elif !OPENSSL_101_API
133	  // for SSL initialization
134	  SSL_load_error_strings();
135	  SSL_library_init();
136	  // Need this to "decrypt" p12 files.
137	  OpenSSL_add_all_algorithms();
138	#  endif // !OPENSSL_101_API
139	#endif   // HAVE_OPENSSL
140	#ifdef HAVE_LIBGCRYPT
141	  if (!gcry_check_version("1.2.4")) {
142	    throw DL_ABORT_EX("gcry_check_version() failed.");
143	  }
144	  gcry_control(GCRYCTL_DISABLE_SECMEM, 0);
