148	extern error_code::Value option_processing(Option& option, bool standalone,
149	                                           std::vector<std::string>& uris,
150	                                           int argc, char** argv,
151	                                           const KeyVals& options);
152	
153	Context::Context(bool standalone, int argc, char** argv, const KeyVals& options)
154	{
155	  std::vector<std::string> args;
156	  auto op = std::make_shared<Option>();
157	  error_code::Value rv;
158	  rv = option_processing(*op.get(), standalone, args, argc, argv, options);
159	  if (rv != error_code::FINISHED) {
160	    if (standalone) {
161	      exit(rv);
162	    }
163	    else {
164	      throw DL_ABORT_EX("Option processing failed");
165	    }
166	  }
167	#ifdef ENABLE_BITTORRENT
168	  bittorrent::generateStaticPeerId(op->get(PREF_PEER_ID_PREFIX));
169	  bittorrent::generateStaticPeerAgent(op->get(PREF_PEER_AGENT));
170	#endif // ENABLE_BITTORRENT
171	  LogFactory::setLogFile(op->get(PREF_LOG));
172	  LogFactory::setLogLevel(op->get(PREF_LOG_LEVEL));
173	  LogFactory::setConsoleLogLevel(op->get(PREF_CONSOLE_LOG_LEVEL));
174	  LogFactory::setColorOutput(op->getAsBool(PREF_ENABLE_COLOR));
175	  if (op->getAsBool(PREF_QUIET)) {
176	    LogFactory::setConsoleOutput(false);
177	  }
178	  LogFactory::reconfigure();
179	  A2_LOG_INFO("<<--- --- --- ---");
180	  A2_LOG_INFO("  --- --- --- ---");
181	  A2_LOG_INFO("  --- --- --- --->>");
182	  A2_LOG_INFO(fmt("%s %s", PACKAGE, PACKAGE_VERSION));
183	  A2_LOG_INFO(usedCompilerAndPlatform());
184	  A2_LOG_INFO(getOperatingSystemInfo());
185	  A2_LOG_INFO(usedLibs());
186	  A2_LOG_INFO(MSG_LOGGING_STARTED);
187	
188	#if defined(HAVE_SYS_RESOURCE_H) && defined(RLIMIT_NOFILE)
189	  rlimit r = {0, 0};
190	  if (getrlimit(RLIMIT_NOFILE, &r) >= 0 && r.rlim_cur != RLIM_INFINITY) {
191	    // Thanks portability, for making it easy :p
192	    auto rlim_new = r.rlim_cur; // So we get the right type for free.
193	    if (r.rlim_cur != RLIM_INFINITY) {
194	      rlim_new = op->getAsInt(PREF_RLIMIT_NOFILE);
195	      rlim_new = std::max(r.rlim_cur, rlim_new);
196	      if (r.rlim_max != RLIM_INFINITY) {
197	        rlim_new = std::min(r.rlim_max, rlim_new);
198	      }
199	    }
200	    if (rlim_new != r.rlim_cur) {
201	      if (setrlimit(RLIMIT_NOFILE, &r) != 0) {
202	        int errNum = errno;
203	        A2_LOG_WARN(fmt("Failed to set rlimit NO_FILE from %" PRIu64 " to "
204	                        "%" PRIu64 ": %s",
205	                        (uint64_t)r.rlim_cur, (uint64_t)rlim_new,
206	                        util::safeStrerror(errNum).c_str()));
207	      }
208	      else {
209	        A2_LOG_DEBUG(fmt("Set rlimit NO_FILE from %" PRIu64 " to %" PRIu64,
210	                         (uint64_t)r.rlim_cur, (uint64_t)rlim_new));
211	      }
212	    }
213	    else {
214	      rlim_new = op->getAsInt(PREF_RLIMIT_NOFILE);
215	      A2_LOG_DEBUG(fmt("Not setting rlimit NO_FILE: %" PRIu64 " >= %" PRIu64,
216	                       (uint64_t)r.rlim_cur, (uint64_t)rlim_new));
217	    }
218	  }
219	#endif // defined(HAVE_SYS_RESOURCE_H) && defined(RLIMIT_NOFILE)
220	
221	  if (op->getAsBool(PREF_DISABLE_IPV6)) {
222	    SocketCore::setProtocolFamily(AF_INET);
223	  }
224	  SocketCore::setIpDscp(op->getAsInt(PREF_DSCP));
225	  SocketCore::setSocketRecvBufferSize(
226	      op->getAsInt(PREF_SOCKET_RECV_BUFFER_SIZE));
227	  net::checkAddrconfig();
228	
229	  if (!net::getIPv4AddrConfigured() && !net::getIPv6AddrConfigured()) {
230	    // Get rid of AI_ADDRCONFIG. It causes name resolution error when
231	    // none of network interface has IPv4/v6 address.
232	    setDefaultAIFlags(0);
233	  }
234	
235	  // Bind interface
236	  if (!op->get(PREF_INTERFACE).empty()) {
237	    std::string iface = op->get(PREF_INTERFACE);
238	    SocketCore::bindAddress(iface);
239	  }
240	  // Bind multiple interfaces
241	  if (!op->get(PREF_MULTIPLE_INTERFACE).empty() &&
242	      op->get(PREF_INTERFACE).empty()) {
243	    std::string ifaces = op->get(PREF_MULTIPLE_INTERFACE);
244	    SocketCore::bindAllAddress(ifaces);
245	  }
246	  std::vector<std::shared_ptr<RequestGroup>> requestGroups;
247	  std::shared_ptr<UriListParser> uriListParser;
248	#ifdef ENABLE_BITTORRENT
249	  if (!op->blank(PREF_TORRENT_FILE)) {
250	    if (op->get(PREF_SHOW_FILES) == A2_V_TRUE) {
251	      showTorrentFile(op->get(PREF_TORRENT_FILE));
252	      return;
253	    }
254	    else {
255	      createRequestGroupForBitTorrent(requestGroups, op, args,
256	                                      op->get(PREF_TORRENT_FILE));
257	    }
258	  }
259	  else
260	#endif // ENABLE_BITTORRENT
261	#ifdef ENABLE_METALINK
262	      if (!op->blank(PREF_METALINK_FILE)) {
263	    if (op->get(PREF_SHOW_FILES) == A2_V_TRUE) {
264	      showMetalinkFile(op->get(PREF_METALINK_FILE), op);
265	      return;
266	    }
267	    else {
268	      createRequestGroupForMetalink(requestGroups, op);
269	    }
270	  }
271	  else
272	#endif // ENABLE_METALINK
273	    if (!op->blank(PREF_INPUT_FILE)) {
274	      if (op->getAsBool(PREF_DEFERRED_INPUT)) {
275	        uriListParser = openUriListParser(op->get(PREF_INPUT_FILE));
276	      }
277	      else {
278	        createRequestGroupForUriList(requestGroups, op);
279	      }
280	#if defined(ENABLE_BITTORRENT) || defined(ENABLE_METALINK)
281	    }
282	    else if (op->get(PREF_SHOW_FILES) == A2_V_TRUE) {
283	      showFiles(args, op);
284	      return;
285	#endif // ENABLE_METALINK || ENABLE_METALINK
286	    }
287	    else {
288	      createRequestGroupForUri(requestGroups, op, args, false, false, true);
289	    }
290	
291	  // Remove option values which is only valid for URIs specified in
292	  // command-line. If they are left, because op is used as a template
293	  // for new RequestGroup(such as created in RPC command), they causes
294	  // unintentional effect.
295	  op->remove(PREF_OUT);
296	  op->remove(PREF_FORCE_SEQUENTIAL);
297	  op->remove(PREF_INPUT_FILE);
298	  op->remove(PREF_INDEX_OUT);
299	  op->remove(PREF_SELECT_FILE);
300	  op->remove(PREF_PAUSE);
301	  op->remove(PREF_CHECKSUM);
302	  op->remove(PREF_GID);
303	
304	  if (standalone && !op->getAsBool(PREF_ENABLE_RPC) && requestGroups.empty() &&
305	      !uriListParser) {
306	    global::cout()->printf("%s\n", MSG_NO_FILES_TO_DOWNLOAD);
307	  }
308	  else {
309	    if (!requestGroups.empty()) {
310	      A2_LOG_NOTICE(fmt("Downloading %" PRId64 " item(s)",
311	                        static_cast<uint64_t>(requestGroups.size())));
312	    }
313	    reqinfo = std::make_shared<MultiUrlRequestInfo>(std::move(requestGroups),
314	                                                    op, uriListParser);
315	  }
316	}
