57	    // This avoids costly unnecessary message formatting and write.
58	    logger->openFile(filename_);
59	  }
60	  logger->setLogLevel(logLevel_);
61	  logger->setConsoleLogLevel(consoleLogLevel_);
62	  logger->setConsoleOutput(consoleOutput_);
63	  logger->setColorOutput(colorOutput_);
64	}
