66	void LogFactory::adjustDependentLevels()
67	{
68	  auto level = consoleLogLevel_;
69	  if (filename_ != DEV_NULL) {
70	    level = std::min(level, logLevel_);
71	  }
72	#ifdef HAVE_LIBGNUTLS
73	  if (level == Logger::A2_DEBUG) {
74	    gnutls_global_set_log_level(6);
75	  }
76	  else {
77	    gnutls_global_set_log_level(0);
78	  }
79	#endif
80	}
