82	void LogFactory::reconfigure()
83	{
84	  if (logger_) {
85	    logger_->closeFile();
86	    try {
87	      openLogger(logger_);
88	    }
89	    catch (RecoverableException& e) {
90	      logger_->closeFile();
91	      throw;
92	    }
93	  }
94	}
