91	static const DWORD mainThread = GetCurrentThreadId();
92	#endif
93	
94	static void handler(int signal)
95	{
96	  if (
97	#ifdef SIGHUP
98	      signal == SIGHUP ||
99	#endif // SIGHUP
100	      signal == SIGTERM) {
101	    if (global::globalHaltRequested <= 2) {
102	      global::globalHaltRequested = 3;
103	    }
104	#ifdef _WIN32
105	    if (::GetCurrentThreadId() != mainThread) {
106	      // SIGTERM may arrive on another thread (via SetConsoleCtrlHandler), and
107	      // the process will be forcefully terminated as soon as that thread is
108	      // done. So better make sure it isn't done prematurely. ;)
109	      while (global::globalHaltRequested != 5) {
110	        ::Sleep(100); // Yeah, semi-busy waiting for now.
111	      }
112	    }
113	#endif
114	    return;
115	  }
116	
117	  // SIGINT
118	
119	  if (global::globalHaltRequested == 0) {
120	    global::globalHaltRequested = 1;
121	    return;
122	  }
123	
124	  if (global::globalHaltRequested == 2) {
125	    global::globalHaltRequested = 3;
126	    return;
127	  }
128	}
