139	      std::chrono::seconds(op->getAsInt(PREF_SUMMARY_INTERVAL)),
140	      op->getAsBool(PREF_ENABLE_COLOR), op->getAsBool(PREF_HUMAN_READABLE));
141	  impl->setReadoutVisibility(op->getAsBool(PREF_SHOW_CONSOLE_READOUT));
142	  impl->setTruncate(op->getAsBool(PREF_TRUNCATE_CONSOLE_READOUT));
143	  return std::move(impl);
