167	{
168	  if (!option_->getAsBool(PREF_QUIET)) {
169	    global::cout()->printf(
170	        "\n%s\n%s\n",
171	        _("aria2 will resume download if the transfer is restarted."),
172	        _("If there are any errors, then see the log file. See '-l' option in "
173	          "help/man page for details."));
174	  }
