177	int MultiUrlRequestInfo::prepare()
178	{
179	  global::globalHaltRequested = 0;
180	  try {
181	    SingletonHolder<Notifier>::instance(make_unique<Notifier>());
182	
183	#ifdef ENABLE_SSL
184	    if (option_->getAsBool(PREF_ENABLE_RPC) &&
185	        option_->getAsBool(PREF_RPC_SECURE)) {
186	      if (option_->blank(PREF_RPC_CERTIFICATE)) {
187	        throw DL_ABORT_EX("Specify --rpc-certificate and --rpc-private-key "
188	                          "options in order to use secure RPC.");
189	      }
190	      // We set server TLS context to the SocketCore before creating
191	      // DownloadEngine instance.
192	      auto minTLSVer = util::toTLSVersion(option_->get(PREF_MIN_TLS_VERSION));
193	      std::shared_ptr<TLSContext> svTlsContext(
194	          TLSContext::make(TLS_SERVER, minTLSVer));
195	      if (!svTlsContext->addCredentialFile(
196	              option_->get(PREF_RPC_CERTIFICATE),
197	              option_->get(PREF_RPC_PRIVATE_KEY))) {
198	        throw DL_ABORT_EX("Loading private key and/or certificate for secure "
199	                          "RPC failed.");
200	      }
201	      SocketCore::setServerTLSContext(svTlsContext);
202	    }
203	#endif // ENABLE_SSL
204	
205	    // RequestGroups will be transferred to DownloadEngine
206	    e_ = DownloadEngineFactory().newDownloadEngine(option_.get(),
207	                                                   std::move(requestGroups_));
208	
209	#ifdef ENABLE_WEBSOCKET
210	    if (option_->getAsBool(PREF_ENABLE_RPC)) {
211	      e_->setWebSocketSessionMan(make_unique<rpc::WebSocketSessionMan>());
212	      SingletonHolder<Notifier>::instance()->addDownloadEventListener(
213	          e_->getWebSocketSessionMan().get());
214	    }
215	#endif // ENABLE_WEBSOCKET
216	
217	    if (!option_->blank(PREF_LOAD_COOKIES)) {
218	      File cookieFile(option_->get(PREF_LOAD_COOKIES));
219	      if (cookieFile.isFile() &&
220	          e_->getCookieStorage()->load(cookieFile.getPath(),
221	                                       Time().getTimeFromEpoch())) {
222	        A2_LOG_INFO(
223	            fmt("Loaded cookies from '%s'.", cookieFile.getPath().c_str()));
224	      }
225	      else {
226	        A2_LOG_ERROR(
227	            fmt(MSG_LOADING_COOKIE_FAILED, cookieFile.getPath().c_str()));
228	      }
229	    }
230	
231	    auto authConfigFactory = make_unique<AuthConfigFactory>();
232	    File netrccf(option_->get(PREF_NETRC_PATH));
233	    if (!option_->getAsBool(PREF_NO_NETRC) && netrccf.isFile()) {
234	#ifdef __MINGW32__
235	      // Windows OS does not have permission, so set it to 0.
236	      mode_t mode = 0;
237	#else  // !__MINGW32__
238	      mode_t mode = netrccf.mode();
239	#endif // !__MINGW32__
240	      if (mode & (S_IRWXG | S_IRWXO)) {
241	        A2_LOG_NOTICE(fmt(MSG_INCORRECT_NETRC_PERMISSION,
242	                          option_->get(PREF_NETRC_PATH).c_str()));
243	      }
244	      else {
245	        auto netrc = make_unique<Netrc>();
246	        netrc->parse(option_->get(PREF_NETRC_PATH));
247	        authConfigFactory->setNetrc(std::move(netrc));
248	      }
249	    }
250	    e_->setAuthConfigFactory(std::move(authConfigFactory));
251	
252	#ifdef ENABLE_SSL
253	    auto minTLSVer = util::toTLSVersion(option_->get(PREF_MIN_TLS_VERSION));
254	    std::shared_ptr<TLSContext> clTlsContext(
255	        TLSContext::make(TLS_CLIENT, minTLSVer));
256	    if (!option_->blank(PREF_CERTIFICATE)) {
257	      clTlsContext->addCredentialFile(option_->get(PREF_CERTIFICATE),
258	                                      option_->get(PREF_PRIVATE_KEY));
259	    }
260	
261	    if (!option_->blank(PREF_CA_CERTIFICATE)) {
262	      if (!clTlsContext->addTrustedCACertFile(
263	              option_->get(PREF_CA_CERTIFICATE))) {
264	        A2_LOG_INFO(MSG_WARN_NO_CA_CERT);
265	      }
266	    }
267	    else if (option_->getAsBool(PREF_CHECK_CERTIFICATE)) {
268	      if (!clTlsContext->addSystemTrustedCACerts()) {
269	        A2_LOG_INFO(MSG_WARN_NO_CA_CERT);
270	      }
271	    }
272	    clTlsContext->setVerifyPeer(option_->getAsBool(PREF_CHECK_CERTIFICATE));
273	    SocketCore::setClientTLSContext(clTlsContext);
274	#endif
275	
276	    std::string serverStatIf = option_->get(PREF_SERVER_STAT_IF);
277	    if (!serverStatIf.empty()) {
278	      e_->getRequestGroupMan()->loadServerStat(serverStatIf);
279	      e_->getRequestGroupMan()->removeStaleServerStat(
280	          std::chrono::seconds(option_->getAsInt(PREF_SERVER_STAT_TIMEOUT)));
281	    }
282	    e_->setStatCalc(getStatCalc(option_));
283	    if (uriListParser_) {
284	      e_->getRequestGroupMan()->setUriListParser(uriListParser_);
285	    }
286	    if (useSignalHandler_) {
287	      setupSignalHandlers();
288	    }
289	    e_->getRequestGroupMan()->getNetStat().downloadStart();
290	  }
291	  catch (RecoverableException& e) {
292	    A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
293	    SingletonHolder<Notifier>::clear();
294	    if (useSignalHandler_) {
295	      resetSignalHandlers();
296	    }
297	    return -1;
298	  }
299	  return 0;
300	}
301	
302	error_code::Value MultiUrlRequestInfo::getResult()
303	{
304	  error_code::Value returnValue = error_code::FINISHED;
305	  if (!option_->blank(PREF_SAVE_COOKIES)) {
306	    e_->getCookieStorage()->saveNsFormat(option_->get(PREF_SAVE_COOKIES));
307	  }
308	
309	  const std::string& serverStatOf = option_->get(PREF_SERVER_STAT_OF);
310	  if (!serverStatOf.empty()) {
311	    e_->getRequestGroupMan()->saveServerStat(serverStatOf);
312	  }
313	  if (!option_->getAsBool(PREF_QUIET) &&
314	      option_->get(PREF_DOWNLOAD_RESULT) != A2_V_HIDE) {
315	    e_->getRequestGroupMan()->showDownloadResults(
316	        *global::cout(), option_->get(PREF_DOWNLOAD_RESULT) == A2_V_FULL);
317	    global::cout()->flush();
318	  }
319	
320	  RequestGroupMan::DownloadStat s = e_->getRequestGroupMan()->getDownloadStat();
321	  if (!s.allCompleted()) {
322	    printMessageForContinue();
323	    if (s.getLastErrorResult() == error_code::FINISHED &&
324	        s.getInProgress() > 0) {
325	      returnValue = error_code::IN_PROGRESS;
326	    }
327	    else {
328	      returnValue = s.getLastErrorResult();
329	    }
330	  }
331	  SessionSerializer sessionSerializer{e_->getRequestGroupMan().get()};
332	  // TODO Add option: --save-session-status=error,inprogress,waiting
333	  if (!option_->blank(PREF_SAVE_SESSION)) {
334	    const std::string& filename = option_->get(PREF_SAVE_SESSION);
335	    if (sessionSerializer.save(filename)) {
336	      A2_LOG_NOTICE(
337	          fmt(_("Serialized session to '%s' successfully."), filename.c_str()));
338	    }
339	    else {
340	      A2_LOG_NOTICE(
341	          fmt(_("Failed to serialize session to '%s'."), filename.c_str()));
342	    }
343	  }
344	  SingletonHolder<Notifier>::clear();
345	  return returnValue;
346	}
347	
348	error_code::Value MultiUrlRequestInfo::execute()
349	{
350	  if (prepare() != 0) {
351	    return error_code::UNKNOWN_ERROR;
352	  }
353	  // TODO Enclosed in try..catch block for just in case. Really need
354	  // this?
355	  try {
356	    e_->run();
357	  }
358	  catch (RecoverableException& e) {
359	    A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
360	  }
361	  error_code::Value returnValue = getResult();
362	  if (useSignalHandler_) {
363	    resetSignalHandlers();
364	  }
365	  return returnValue;
366	}
367	
368	void MultiUrlRequestInfo::setupSignalHandlers()
369	{
370	#ifdef HAVE_SIGACTION
371	  sigemptyset(&mask_);
372	#else  // !HAVE_SIGACTION
373	  mask_ = 0;
374	#endif // !HAVE_SIGACTION
375	#ifdef SIGPIPE
376	  util::setGlobalSignalHandler(SIGPIPE, &mask_, SIG_IGN, 0);
377	#endif // SIGPIPE
378	#ifdef SIGCHLD
379	  // Avoid to create zombie process when forked child processes are
380	  // died.
381	  util::setGlobalSignalHandler(SIGCHLD, &mask_, SIG_IGN, 0);
382	#endif // SIGCHILD
383	
384	#ifdef HAVE_SIGACTION
385	  sigaddset(&mask_, SIGINT);
386	  sigaddset(&mask_, SIGTERM);
387	#  ifdef SIGHUP
388	  sigaddset(&mask_, SIGHUP);
389	#  endif // SIGHUP
390	#endif   // HAVE_SIGACTION
391	
392	#ifdef SIGHUP
393	  util::setGlobalSignalHandler(SIGHUP, &mask_, handler, 0);
394	#endif // SIGHUP
395	  util::setGlobalSignalHandler(SIGINT, &mask_, handler, 0);
396	  util::setGlobalSignalHandler(SIGTERM, &mask_, handler, 0);
397	}
398	
399	void MultiUrlRequestInfo::resetSignalHandlers()
400	{
401	#ifdef HAVE_SIGACTION
402	  sigemptyset(&mask_);
403	#endif // HAVE_SIGACTION
404	#ifdef SIGHUP
405	  util::setGlobalSignalHandler(SIGHUP, &mask_, SIG_DFL, 0);
406	#endif // SIGHUP
407	  util::setGlobalSignalHandler(SIGINT, &mask_, SIG_DFL, 0);
408	  util::setGlobalSignalHandler(SIGTERM, &mask_, SIG_DFL, 0);
409	
410	#ifdef SIGCHLD
411	  util::setGlobalSignalHandler(SIGCHLD, &mask_, SIG_DFL, 0);
412	#endif // SIGCHILD
413	#ifdef SIGPIPE
414	  util::setGlobalSignalHandler(SIGPIPE, &mask_, SIG_DFL, 0);
415	#endif // SIGPIPE
416	}
417	
418	const std::unique_ptr<DownloadEngine>&
419	MultiUrlRequestInfo::getDownloadEngine() const
420	{
421	  return e_;
422	}
423	
424	} // namespace aria2
